import random
import string
import pandas as pd

def task_func(data_list, seed=0):
    rng = random.Random(seed)

    def _random_lowercase(n):
        return "".join(rng.choice(string.ascii_lowercase) for _ in range(n))

    rows = []
    for original in data_list:
        parts = original.split(",")
        non_empty_indices = [i for i, part in enumerate(parts) if part]

        # Prefer replacing a non-empty comma-delimited substring when possible.
        # If the string contains only empty segments (e.g., "," or ",,"),
        # fall back to choosing any segment; replacing an empty segment keeps
        # the string unchanged, which is the only length-preserving option.
        if non_empty_indices:
            idx = rng.choice(non_empty_indices)
        else:
            idx = rng.randrange(len(parts))

        parts[idx] = _random_lowercase(len(parts[idx]))
        modified = ",".join(parts)

        rows.append({
            "Original String": original,
            "Modified String": modified
        })

    return pd.DataFrame(rows, columns=["Original String", "Modified String"])
